@Test
void testFace_getDefinedCompositeNormal_1_oe() {
    // arrange
    final PolygonObjParser p = parser(lines(
            "v 0 0 0",
            "v 1 0 0",
            "v 1 1 0",
            "v 0 1 0",
            "",
            "vn 0 0 1",
            "vn 0 0 -1",
            "vn 2 2 2",
            "vn -2 2 2",
            "",
            "f 1 2 3 4",
            "f 1//1 2 3",
            "f 1//1 2//1 3//1 4//1",
            "f 1//1 2//2 3//1 4//2",
            "f 1//-2 2//-1 3//3 4//4"
    ));

    final List<Vector3D> normals = Arrays.asList(
            Vector3D.Unit.PLUS_Z,
            Vector3D.Unit.MINUS_Z,
            Vector3D.of(1, 1, 1),
            Vector3D.of(-1, 1, 1));
    final IntFunction<Vector3D> normalFn = normals::get;

    // act/assert
    nextMatchingKeyword("f", p);
    Assertions.assertNull(p.readFace().getDefinedCompositeNormal(normalFn));
}

mut_method_definition:
public Vector3D getDefinedCompositeNormal(final IntFunction<Vector3D> modelNormalFn) {
            Vector3D sum = Vector3D.ZERO;

            int normalIdx;
            for (final VertexAttributes vertex : vertexAttributes) {
                normalIdx = vertex.getNormalIndex();
                if (normalIdx > -1) {
                    sum = sum.add(modelNormalFn.apply(normalIdx));
                }
            }

            return sum.normalizeOrNull();
        }

