void testRegionBSPTree1DExample_1_oe() {
    final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-6);

    // build a bsp tree from the union of several intervals
    final RegionBSPTree1D tree = RegionBSPTree1D.empty();

    tree.add(Interval.of(1, 2, precision));
    tree.add(Interval.of(1.5, 3, precision));
    tree.add(Interval.of(-1, -2, precision));

    // compute the size;
    final double size = tree.getSize(); // 3

    // convert back to intervals
    final List<Interval> intervals = tree.toIntervals(); // size = 2

    // ----------------------
    Assertions.assertEquals(3, size, TEST_EPS);
}

mut_method_definition:
public List<Interval> toIntervals() {

        final List<BoundaryPair> boundaryPairs = new ArrayList<>();

        visitInsideIntervals((min, max) -> boundaryPairs.add(new BoundaryPair(min, max)));
        boundaryPairs.sort(BOUNDARY_PAIR_COMPARATOR);

        final List<Interval> intervals = new ArrayList<>();

        BoundaryPair start = null;
        BoundaryPair end = null;

        for (final BoundaryPair current : boundaryPairs) {
            if (start == null) {
                start = current;
                end = current;
            } else if (Objects.equals(end.getMax(), current.getMin())) {
                // these intervals should be merged
                end = current;
            } else {
                // these intervals should not be merged
                intervals.add(createInterval(start, end));

                // queue up the next pair
                start = current;
                end = current;
            }
        }

        if (start != null) {
            intervals.add(createInterval(start, end));
        }

        return intervals;
    }

