void testSimplify_startAndEndNotCombinedWhenNotClosed_1_oe() {
    // arrange
    final Line xAxis = Lines.fromPointAndAngle(Vector2D.ZERO, 0.0, TEST_PRECISION);
    final Builder builder = LinePath.builder(TEST_PRECISION);

