mut_method_definition:
public Bounds3D getBounds(final BoundarySource3D src) {
        final Bounds3D.Builder builder = Bounds3D.builder();

        try (Stream<PlaneConvexSubset> stream = src.boundaryStream()) {
            final Iterator<PlaneConvexSubset> it = stream.iterator();

            PlaneConvexSubset boundary;
            while (it.hasNext()) {
                boundary = it.next();

                if (!boundary.isFinite()) {
                    return null;
                }

                builder.addAll(boundary.getVertices());
            }
        }

        return builder.hasBounds() ?
                builder.build() :
                null;
    }

test_prefix:
@Test
void testGetBounds_singleFiniteBoundary_1_oe() {
    // arrange
    final ConvexPolygon3D poly = Planes.convexPolygonFromVertices(Arrays.asList(
            Vector3D.of(1, 1, 1),
            Vector3D.of(1, 0, 2),
            Vector3D.of(3, 4, 5)), TEST_PRECISION);

    final BoundarySource3D src = BoundarySource3D.of(poly);
    final BoundarySourceBoundsBuilder3D builder = new BoundarySourceBoundsBuilder3D();

    // act
    final Bounds3D b = builder.getBounds(src);

    // assert
    checkBounds(b, Vector3D.of(1, 0, 1), Vector3D.of(3, 4, 5));
    for (final Vector3D pt : poly.getVertices()) {
        Assertions.assertTrue(b.contains(pt));
}
}

mut_method_definition:
@Override
    public boolean contains(final Vector3D pt) {
        final double x = pt.getX();
        final double y = pt.getY();
        final double z = pt.getZ();

        final Vector3D min = getMin();
        final Vector3D max = getMax();

        return x >= min.getX() && x <= max.getX() &&
                y >= min.getY() && y <= max.getY() &&
                z >= min.getZ() && z <= max.getZ();
    }

