            PlaneConvexSubset boundary;
            while (it.hasNext()) {
                boundary = it.next();

                if (!boundary.isFinite()) {
                    return null;
                }

                builder.addAll(boundary.getVertices());
            }
        }

        return builder.hasBounds() ?
                builder.build() :
                null;
    }

