public SplitLocation getLocation() {
        if (minus != null) {
            return plus != null ? SplitLocation.BOTH : SplitLocation.MINUS;
        } else if (plus != null) {
            return SplitLocation.PLUS;
        }
        return SplitLocation.NEITHER;
    }

