            (2 * Math.cos(inc)) + 2,
            (2 * Math.sin(inc)) + 1);
    final Vector2D p2 = Vector2D.of(
            (2 * Math.cos(2 * inc)) + 2,
            (2 * Math.sin(2 * inc)) + 1);

            final LineConvexSubset segment0 = segments.get(0);
    final Vector2D start0 = p0;
    final Vector2D end0 = p1;
    Assertions.assertFalse(segment0.isInfinite());
}

