@Test
void testMeshBuffer_1_oe() {
    // arrange
    final StringWriter writer = new StringWriter();

    try (ObjWriter objWriter = new ObjWriter(writer)) {
        ObjWriter.MeshBuffer buf = objWriter.meshBuffer();

        // act
        buf.add(new SimpleFacetDefinition(Arrays.asList(
                Vector3D.ZERO, Vector3D.of(1, 0, 0), Vector3D.of(1, 1, 0)), Vector3D.Unit.MINUS_Z));
        buf.add(Planes.convexPolygonFromVertices(Arrays.asList(
                Vector3D.ZERO, Vector3D.of(1, 1, 0), Vector3D.of(0, 1.5, 0)), TEST_PRECISION));
        buf.add(new SimpleFacetDefinition(Arrays.asList(
                Vector3D.of(0, 1.5, 0), Vector3D.of(1, 1, 0), Vector3D.of(0, 2, 0)), Vector3D.Unit.PLUS_Z));

        buf.flush();
    }

    // assert
    Assertions.assertEquals("v 0.0 0.0 0.0\n" + "v 1.0 0.0 0.0\n" + "v 1.0 1.0 0.0\n" + "v 0.0 1.5 0.0\n" + "v 0.0 2.0 0.0\n" + "vn 0.0 0.0 -1.0\n" + "vn 0.0 0.0 1.0\n" + "f 1//1 2//1 3//1\n" + "f 1 3 4\n" + "f 4//2 3//2 5//2\n",writer.getBuffer().toString());
}

mut_docstring:
/** Flush the buffer content to the output and reset its state.
         * @throws java.io.UncheckedIOException if an I/O error occurs
         */

mut_method_definition:
public void flush() {
            final int vertexOffset = vertexCount;
            final int normalOffset = normalCount;

            // write vertices
            for (final String vertexStr : vertexMap.keySet()) {
                writeVertexLine(vertexStr);
            }

            // write normals
            for (final String normalStr : normalMap.keySet()) {
                writeVertexNormalLine(normalStr);
            }

            // write faces
            Integer normalIndex;
            int[] normalIndices;
            int faceIndex = 0;
            for (final int[] vertexIndices : faceVertices) {
                normalIndex = faceToNormalMap.get(faceIndex);
                if (normalIndex != null) {
                    normalIndices = new int[vertexIndices.length];
                    Arrays.fill(normalIndices, normalIndex);
                } else {
                    normalIndices = null;
                }

                writeFaceWithOffsets(vertexOffset, vertexIndices, normalOffset, normalIndices);

                ++faceIndex;
            }

            reset();
        }

