mut_method_definition:
@Override
    public FacetDefinition readFacet() {
        discardNonDataLines();
        if (parser.hasMoreCharacters()) {
            try {
                return readFacetInternal();
            } finally {
                // advance to the next line even if parsing failed for the
                // current line
                parser.discardLine();
            }
        }
        return null;
    }

